    ///
    /// # async fn dox() -> std::io::Result<()> {
    /// let file = File::open("foo.txt").await?;
    /// let mut perms = file.metadata().await?.permissions();
    /// perms.set_readonly(true);
    /// file.set_permissions(perms).await?;
    /// # Ok(())
    /// # }
    /// ```
    pub async fn set_permissions(&self, perm: Permissions) -> io::Result<()> {
        let std = self.std.clone();
        asyncify(move || std.set_permissions(perm)).await
    }

    /// Set the maximum buffer size for the underlying [`AsyncRead`] / [`AsyncWrite`] operation.
    ///
    /// Although Tokio uses a sensible default value for this buffer size, this function would be
    /// useful for changing that default depending on the situation.
    ///
    /// # Examples
    ///
    /// ```no_run
    /// use tokio::fs::File;
    /// use tokio::io::AsyncWriteExt;
    ///
    /// # async fn dox() -> std::io::Result<()> {
    /// let mut file = File::open("foo.txt").await?;
    ///
    /// // Set maximum buffer size to 8 MiB
    /// file.set_max_buf_size(8 * 1024 * 1024);
    ///
    /// let mut buf = vec![1; 1024 * 1024 * 1024];
    ///
    /// // Write the 1 GiB buffer in chunks up to 8 MiB each.
    /// file.write_all(&mut buf).await?;
    /// # Ok(())
    /// # }
    /// ```
    pub fn set_max_buf_size(&mut self, max_buf_size: usize) {
        self.max_buf_size = max_buf_size;
    }

    fn copy_buffered_read(
        &self,
        buf: &mut Buf,
        dst: &mut ReadBuf<'_>,
    ) -> Option<(Arc<StdFile>, usize)> {
        let buffered = buf.buf.len() - buf.pos;
        let space = dst.buf.len() - dst.filled;

        if buffered == 0 {
            let max_buf_size = cmp::min(space, self.max_buf_size);
            return Some((self.std.clone(), max_buf_size));
        }

        let n = cmp::min(buffered, space);
        if n > 0 {
            let end = dst.filled + n;
            // SAFETY: `n` fits in both the unread source bytes and destination capacity.
            unsafe {
                dst.buf[dst.filled..end]
                    .as_mut_ptr()
                    .cast::<u8>()
                    .copy_from_nonoverlapping(buf.buf[buf.pos..].as_ptr(), n);
            }
            if dst.initialized < end {
                dst.initialized = end;
            }
            dst.filled = end;
            buf.pos += n;
        }

        if buf.pos == buf.buf.len() {
            buf.buf.truncate(0);
            buf.pos = 0;
        }

        None
    }
}

impl AsyncRead for File {
    fn poll_read(
        self: Pin<&mut Self>,
        cx: &mut Context<'_>,
        dst: &mut ReadBuf<'_>,
    ) -> Poll<io::Result<()>> {
        ready!(crate::trace::trace_leaf(cx));
        let me = self.get_mut();

        loop {
            let idle_buf = {
                let inner = me.inner.get_mut();
                match inner.state {
                    State::Idle(ref mut buf_cell) => Some(buf_cell.take().unwrap()),
                    State::Busy(_) => None,
                }
            };

            if let Some(mut buf) = idle_buf {
                if let Some((std, max_buf_size)) = me.copy_buffered_read(&mut buf, dst) {
                    me.inner.get_mut().state = State::Busy(spawn_blocking(move || {
                        // SAFETY: the `Read` implementation of `std` does not
                        // read from the buffer it is borrowing and correctly
                        // reports the length of the data written into the buffer.
                        let res = unsafe { buf.read_from(&mut &*std, max_buf_size) };
                        (Operation::Read(res), buf)
                    }));
                    continue;
                }

                match me.inner.get_mut().state {
                    State::Idle(ref mut buf_cell) => *buf_cell = Some(buf),
                    State::Busy(_) => unreachable!(),
                }
                return Poll::Ready(Ok(()));
            }

            let inner = me.inner.get_mut();
            match inner.state {
                State::Idle(_) => unreachable!(),
                State::Busy(ref mut rx) => {
                    let (op, mut buf) = ready!(Pin::new(rx).poll(cx))?;

                    match op {
                        Operation::Read(Ok(_)) => {
                            let n = cmp::min(buf.buf.len() - buf.pos, dst.remaining());
                            dst.put_slice(&buf.buf[buf.pos..buf.pos + n]);
                            buf.pos += n;
                            if buf.pos == buf.buf.len() {
                                buf.buf.truncate(0);
                                buf.pos = 0;
                            }
                            inner.state = State::Idle(Some(buf));
                            return Poll::Ready(Ok(()));
                        }
                        Operation::Read(Err(e)) => {
                            assert!(buf.is_empty());

                            inner.state = State::Idle(Some(buf));
                            return Poll::Ready(Err(e));
                        }
                        Operation::Write(Ok(())) => {
                            assert!(buf.is_empty());
                            inner.state = State::Idle(Some(buf));
                            continue;
                        }
                        Operation::Write(Err(e)) => {
                            assert!(inner.last_write_err.is_none());
                            inner.last_write_err = Some(e.kind());
                            inner.state = State::Idle(Some(buf));
                        }
                        Operation::Seek(result) => {
                            assert!(buf.is_empty());
                            inner.state = State::Idle(Some(buf));
                            if let Ok(pos) = result {
                                inner.pos = pos;
                            }
                            continue;
                        }
                    }
                }
            }
        }
    }
}

