use std::{pin::Pin, task::Context};

use futures::task::noop_waker_ref;
use tokio::io::{AsyncRead as _, AsyncReadExt as _, ReadBuf};

#[tokio::test(flavor = "current_thread")]
async fn poll_read_empty_buf_does_not_signal_eof() {
    let mut file = tokio::fs::File::open("/dev/zero").await.unwrap();
    let poll = Pin::new(&mut file).poll_read(
        &mut Context::from_waker(noop_waker_ref()),
        &mut ReadBuf::new(&mut []),
    );
    assert!(matches!(poll, std::task::Poll::Ready(Ok(()))));
    file.read_exact(&mut [0; 4096]).await.unwrap();
}

#[tokio::test(flavor = "current_thread")]
async fn poll_read_empty_buf_then_real_eof() {
    let temp = tempfile::tempdir().unwrap();
    let path = temp.path().join("empty-file");
    std::fs::File::create(&path).unwrap();

    let mut file = tokio::fs::File::open(&path).await.unwrap();
    let poll = Pin::new(&mut file).poll_read(
        &mut Context::from_waker(noop_waker_ref()),
        &mut ReadBuf::new(&mut []),
    );
    assert!(matches!(poll, std::task::Poll::Ready(Ok(()))));

    // Still reports EOF on a subsequent read with a nonempty buffer.
    let mut buf = [0u8; 16];
    let n = file.read(&mut buf).await.unwrap();
    assert_eq!(n, 0);
}

